/*
 * This file was generated by the Gradle 'init' task.
 */

plugins {
    `java-library`
    `maven-publish`
}

repositories {
    mavenLocal()
    maven {
        url = uri("https://repo.papermc.io/repository/maven-public/")
    }

    maven {
        url = uri("https://oss.sonatype.org/content/groups/public/")
    }

    maven {
        url = uri("https://repo.maven.apache.org/maven2/")
    }
}

dependencies {
    api(libs.org.bstats.bstats.bukkit)
    testImplementation(libs.org.junit.platform.junit.platform.engine)
    testImplementation(libs.org.junit.jupiter.junit.jupiter.api)
    testImplementation(libs.org.junit.jupiter.junit.jupiter.params)
    testImplementation(libs.org.mockbukkit.mockbukkit.mockbukkit.v26.v1.v2)
    compileOnly(libs.io.papermc.paper.paper.api)
    compileOnly(libs.net.kyori.adventure.text.serializer.legacy)
}

group = "com.atlasgong"
version = "3.2.3-SNAPSHOT"
description = "InvisibleItemFramesLite"
java.sourceCompatibility = JavaVersion.VERSION_25

publishing {
    publications.create<MavenPublication>("maven") {
        from(components["java"])
    }
}

tasks.withType<JavaCompile>() {
    options.encoding = "UTF-8"
}

tasks.withType<Javadoc>() {
    options.encoding = "UTF-8"
}
